"""Real RPC grants, registration replay and session/revocation fencing."""

import asyncio
import os
import secrets
import subprocess
import uuid

import httpx
import pytest

from oshepherd.backends.supabase.client import RpcClient, RpcError
from oshepherd.backends.supabase.sessions import WorkerAuth


def cleanup_cluster(cluster_id, *, schema="oshepherd_spike"):
    # UUID is generated by this test, validated before use, and passed as a psql
    # variable. Cleanup affects only this test's rows in the isolated namespace.
    cluster_id = str(uuid.UUID(cluster_id))
    assert schema in ("oshepherd_spike", "oshepherd")
    sql = """
    begin;
    delete from oshepherd_spike.worker_operations where worker_id in (select id from oshepherd_spike.workers where cluster_id = :'cluster_id'::uuid);
    delete from oshepherd_spike.jobs where cluster_id = :'cluster_id'::uuid;
    delete from oshepherd_spike.admin_operations where
      response #>> '{data,cluster_id}' = :'cluster_id' or
      response #>> '{data,key_id}' in (select id::text from oshepherd_spike.api_keys where cluster_id = :'cluster_id'::uuid) or
      response #>> '{data,worker_id}' in (select id::text from oshepherd_spike.workers where cluster_id = :'cluster_id'::uuid);
    delete from oshepherd_spike.worker_models where worker_id in (select id from oshepherd_spike.workers where cluster_id = :'cluster_id'::uuid);
    delete from oshepherd_spike.worker_sessions where worker_id in (select id from oshepherd_spike.workers where cluster_id = :'cluster_id'::uuid);
    delete from oshepherd_spike.workers where cluster_id = :'cluster_id'::uuid;
    delete from oshepherd_spike.api_keys where cluster_id = :'cluster_id'::uuid;
    delete from oshepherd_spike.memberships where cluster_id = :'cluster_id'::uuid;
    delete from oshepherd_spike.clusters where id = :'cluster_id'::uuid;
    commit;
    """
    sql = sql.replace("oshepherd_spike", schema)
    result = subprocess.run(
        [
            "psql",
            "-h",
            "127.0.0.1",
            "-p",
            "55322",
            "-U",
            "postgres",
            "-d",
            "postgres",
            "-v",
            "ON_ERROR_STOP=1",
            "-v",
            "cluster_id=" + cluster_id,
        ],
        input=sql,
        env={**os.environ, "PGPASSWORD": "postgres"},
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, "Scoped spike test cleanup failed"


def test_identity_grants_replay_and_fencing(local_connection):
    async def run():
        origin = local_connection["API_URL"]
        subjects = []
        clusters = [str(uuid.uuid4()), str(uuid.uuid4())]
        async with httpx.AsyncClient(timeout=10) as client:
            admin_headers = {"apikey": local_connection["SECRET_KEY"]}
            admin = RpcClient(
                origin,
                local_connection["SECRET_KEY"],
                schema="oshepherd_spike_api",
                client=client,
            )

            async def identity(label, signin=False):
                email = f"spike-{label}-{uuid.uuid4()}@enrollment.invalid"
                response = await client.post(
                    origin + "/auth/v1/admin/users",
                    headers=admin_headers,
                    json={"email": email, "email_confirm": True},
                )
                assert response.status_code in (
                    200,
                    201,
                ), "Temporary Auth identity creation failed"
                subject = response.json()["id"]
                subjects.append(subject)
                if not signin:
                    return subject
                response = await client.post(
                    origin + "/auth/v1/admin/generate_link",
                    headers=admin_headers,
                    json={"type": "magiclink", "email": email},
                )
                assert response.status_code == 200
                session = await WorkerAuth(
                    origin, local_connection["PUBLISHABLE_KEY"], client=client
                ).enroll(response.json()["hashed_token"])
                return subject, RpcClient(
                    origin,
                    local_connection["PUBLISHABLE_KEY"],
                    access_token=session.access_token.get_secret_value(),
                    schema="oshepherd_spike_api",
                    client=client,
                )

            try:
                owner = await identity("owner")
                for cluster in clusters:
                    request = {
                        "cluster_id": cluster,
                        "owner_subject": owner,
                        "operation_id": str(uuid.uuid4()),
                    }
                    first = await admin.rpc("bootstrap_cluster", request)
                    assert first == await admin.rpc("bootstrap_cluster", request)
                    assert first == {"cluster_id": cluster}
                key_request = {
                    "cluster_id": clusters[0],
                    "key_id": str(uuid.uuid4()),
                    "raw_key": "osk_" + secrets.token_urlsafe(32),
                    "operation_id": str(uuid.uuid4()),
                }
                key_result = await admin.rpc("create_api_key", key_request)
                assert set(key_result) == {"key_id", "cluster_id"}
                assert key_result == await admin.rpc("create_api_key", key_request)
                with pytest.raises(RpcError, match="idempotency_conflict"):
                    await admin.rpc(
                        "create_api_key",
                        {**key_request, "raw_key": "osk_" + secrets.token_urlsafe(32)},
                    )
                registered = []
                for index, cluster in enumerate(clusters):
                    subject, worker = await identity(str(index), signin=True)
                    enrollment = {
                        "cluster_id": cluster,
                        "auth_subject": subject,
                        "capacity": 1,
                        "operation_id": str(uuid.uuid4()),
                    }
                    bound = await admin.rpc("enroll_worker", enrollment)
                    assert bound == await admin.rpc("enroll_worker", enrollment)
                    operation = str(uuid.uuid4())
                    initial = await worker.rpc(
                        "register_worker", {"operation_id": operation}
                    )
                    replay = await worker.rpc(
                        "register_worker", {"operation_id": operation}
                    )
                    assert initial["worker_id"] == bound["worker_id"]
                    assert initial["cluster_id"] == cluster
                    assert initial["generation"] == replay["generation"] == 1
                    assert initial["session_id"] == replay["session_id"]
                    restarted = await worker.rpc("register_worker", {})
                    assert restarted["generation"] == 2
                    assert restarted["session_id"] != initial["session_id"]
                    with pytest.raises(RpcError, match="stale_session"):
                        await worker.rpc("register_worker", {"operation_id": operation})
                    with pytest.raises(RpcError):
                        await worker.rpc(
                            "bootstrap_cluster",
                            {"cluster_id": str(uuid.uuid4()), "owner_subject": subject},
                        )
                    with pytest.raises(RpcError):
                        await worker.rpc(
                            "register_worker", {"worker_id": initial["worker_id"]}
                        )
                    registered.append((bound, worker))
                assert registered[0][0]["worker_id"] != registered[1][0]["worker_id"]
                _, unenrolled = await identity("unenrolled", signin=True)
                with pytest.raises(RpcError, match="forbidden"):
                    await unenrolled.rpc("register_worker", {})
                anonymous = RpcClient(
                    origin,
                    local_connection["PUBLISHABLE_KEY"],
                    schema="oshepherd_spike_api",
                    client=client,
                )
                with pytest.raises(RpcError):
                    await anonymous.rpc("register_worker", {})
                bound, worker = registered[0]
                revocation = {
                    "cluster_id": clusters[0],
                    "worker_id": bound["worker_id"],
                    "operation_id": str(uuid.uuid4()),
                }
                assert await admin.rpc("revoke_worker", revocation) == await admin.rpc(
                    "revoke_worker", revocation
                )
                with pytest.raises(RpcError, match="worker_revoked"):
                    await worker.rpc("register_worker", {})
            finally:
                for cluster in clusters:
                    cleanup_cluster(cluster)
                for subject in subjects:
                    response = await client.delete(
                        origin + "/auth/v1/admin/users/" + subject,
                        headers=admin_headers,
                    )
                    assert response.status_code in (
                        200,
                        204,
                    ), "Temporary Auth identity cleanup failed"

    asyncio.run(run())
